/**
 * frontend/src/components/Dashboard.jsx
 * Version Premium - Design Attirant (Bleu principal + Rouge & Vert accents)
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',        // Bleu principal (gardé comme avant)
  primaryLight: '#EEF2FF',

  red: '#FF0033',            // Rouge vif pour accents
  redLight: '#FFE6E6',

  green: '#00D4A5',          // Vert clair moderne
  greenLight: '#E6FFF8',

  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF',
};

const Dashboard = ({ addNotification }) => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });
  useEffect(() => {
          console.log("Stats reçues:", stats);
        }, [stats]);


  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [showAll, setShowAll] = useState(false);

  // ====================== CHARGEMENT DES DONNÉES ======================
  const loadData = async () => {
    try {
      setError(null);
      setLoading(true);

      const [studentStatsRes, attendanceStatsRes, logRes, statusRes] = await Promise.all([
        studentsAPI.getStats(),
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      if (!studentStatsRes?.success) throw new Error(studentStatsRes?.error || "Impossible de charger les statistiques étudiants");
      if (!attendanceStatsRes?.success) throw new Error(attendanceStatsRes?.error || "Impossible de charger les statistiques de présence");
      if (!logRes?.success) throw new Error(logRes?.error || "Impossible de charger le journal des présences");
      if (!statusRes?.success) throw new Error(statusRes?.error || "Impossible de charger le statut des étudiants");

      const sData = studentStatsRes.data || {};
      const active = Number(sData.active_students) || 0;
      const logs = Array.isArray(logRes.data?.records) ? logRes.data.records : [];
      const presentToday = new Set(logs.map(r => r.student_id || r.id)).size;

      setStats({
        active_students: active,
        present_today: presentToday,
        absent_today: Math.max(0, active - presentToday),
        summary: attendanceStatsRes.data || {}
      });

      setAttendanceLog(logs);
      setStatusList(Array.isArray(statusRes.data?.students) ? statusRes.data.students : []);

      setLastUpdated(new Date().toLocaleTimeString('fr-FR', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      }));

      setLoading(false);
    } catch (err) {
      setLoading(false);
      const errorMessage = err.message || 'Erreur de connexion au serveur';
      setError(errorMessage);
      if (addNotification) addNotification('Erreur lors du chargement du dashboard', 'error');
    }
  };

  const handleRefresh = () => {
    setRefreshing(true);
    setTimeout(async () => {
      await loadData();
      setRefreshing(false);
    }, 1800);
  };

  useEffect(() => {
    loadData();
  }, []);

  if (loading) {
    return <div style={styles.loading}>Chargement en cours...</div>;
  }

  if (error) {
    return (
      <div style={styles.container}>
        <div style={styles.errorCard}>
          <h3 style={styles.errorTitle}>Erreur de synchronisation</h3>
          <p style={styles.errorText}>{error}</p>
          <p style={styles.errorHint}>
            Vérifiez que le backend est en cours d'exécution et que tous les endpoints sont accessibles.
          </p>
          <button 
            onClick={handleRefresh} 
            style={styles.retryBtn} 
            disabled={refreshing}
          >
            {refreshing ? 'Rafraîchissement...' : 'Réessayer'}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* HEADER */}
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Tableau de Bord</h2>
          <p style={styles.subtitle}>
            Suivi des présences en temps réel • Dernière mise à jour : {lastUpdated || '—'}
          </p>
        </div>
        <button 
          onClick={handleRefresh} 
          style={styles.refreshBtn} 
          disabled={refreshing}
        >
          {refreshing ? 'Actualisation...' : 'Actualiser'}
        </button>
      </div>

      {/* CARTES DE STATISTIQUES - Design moderne avec ombres colorées */}
      <div style={styles.statsGrid}>
        <StatCard label="Étudiants inscrits" value={stats.active_students} accent={COLORS.primary} />
        <StatCard label="Présents aujourd'hui" value={stats.present_today} accent={COLORS.green} />
        <StatCard label="Absents aujourd'hui" value={stats.absent_today} accent={COLORS.red} />
        <StatCard 
          label="Taux de présence" 
          value={stats.active_students > 0 ? `${((stats.present_today / stats.active_students) * 100).toFixed(1)}%` : 'N/A'} 
          accent={
            stats.active_students > 0 && (stats.present_today / stats.active_students) >= 0.8 
              ? COLORS.green 
              : COLORS.red
          }
        />
      </div>

      <div style={styles.mainGrid}>
        {/* DERNIERS SCANS */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Derniers scans aujourd’hui</h3>
          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}>Aucune présence enregistrée aujourd’hui.</div>
          ) : (
            <div role="table" style={styles.table}>
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Étudiant</div>
                <div style={{ flex: 1 }}>Confiance</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>
              {attendanceLog.slice(0, showAll ? attendanceLog.length : 10).map((record, index) => (
                <div key={index} style={styles.tableRow}>
                  <div style={{ flex: 2, fontWeight: 500 }}>{record.student || record.name || 'Inconnu'}</div>
                  <div style={{ flex: 1 }}><ConfidenceBadge confidence={record.confidence} /></div>
                  <div style={{ flex: 1, color: COLORS.textMuted }}>
                    {record.timestamp ? new Date(record.timestamp).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }) : '—'}
                  </div>
                </div>
              ))}
            </div>
          )}
          <div style={styles.tableInfo}>
            Total aujourd’hui : {attendanceLog.length} scans
            {attendanceLog.length > 10 && (
              <button onClick={() => setShowAll(!showAll)} style={styles.viewMoreBtn}>
                {showAll ? "Voir moins" : "Voir plus"}
              </button>
            )}
          </div>
        </div>

        {/* ANALYSE DU PIPELINE */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>Analyse du pipeline</h3>
          <div style={styles.summaryBox}>
            <SummaryItem label="Total scans aujourd’hui" value={stats.summary?.total_records || 0} color={COLORS.primary} />
            <SummaryItem label="Précision moyenne" value={stats.summary?.avg_confidence ? `${(stats.summary.avg_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.green} />
            <SummaryItem label="Meilleure précision" value={stats.summary?.max_confidence ? `${(stats.summary.max_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.green} />
            <SummaryItem label="Précision minimale" value={stats.summary?.min_confidence ? `${(stats.summary.min_confidence * 100).toFixed(1)}%` : 'N/A'} color={COLORS.red} />
          </div>
        </div>
      </div>

      {/* LISTE DES ÉTUDIANTS */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>Liste des étudiants</h3>
        {stats.students && stats.students.length === 0 ? (
          <div style={styles.emptyState}>Aucun étudiant trouvé.</div>
        ) : (
          <div role="table" style={styles.table}>
            <div style={styles.tableHeader}>
              <div style={{ flex: 2 }}>Nom</div>
              <div style={{ flex: 2 }}>Email</div>
              <div style={{ flex: 1 }}>Statut</div>
            </div>
            {stats.students && stats.students.map((student, index) => (
                <div key={student.student_id || index} style={styles.tableRow}>
                <div style={{ flex: 2, fontWeight: 500 }}>{student.name || 'Inconnu'}</div>
                <div style={{ flex: 2, color: COLORS.textMuted, fontSize: '0.95rem' }}>{student.email || '—'}</div>
                <div style={{ flex: 1 }}><StatusBadge present={student.present} /></div>
              </div>
            ))}
          </div>
        )}
        <div style={styles.tableInfo}>
          Total : {stats.students ? stats.students.length : 0} étudiants • {stats.students ? stats.students.filter(s => s.present).length : 0} présents
        </div>
      </div>
    </div>
  );
};


// ==================== SOUS-COMPOSANTS ====================
const StatCard = ({ label, value, accent }) => (
  <div style={{
    ...styles.statCard,
    boxShadow: `0 10px 25px -5px ${accent}25, 0 4px 10px -2px rgba(0,0,0,0.08)`,
    borderLeft: `6px solid ${accent}`
  }}>
    <div style={styles.statContent}>
      <p style={styles.statLabel}>{label}</p>
      <p style={{ ...styles.statValue, color: accent }}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ confidence }) => {
  const score = Number(confidence) || 0;
  const percentage = (score * 100).toFixed(0);
  let color = COLORS.red;
  let bg = COLORS.redLight;

  if (score > 0.7) { color = COLORS.green; bg = COLORS.greenLight; }
  else if (score > 0.4) { color = COLORS.primary; bg = COLORS.primaryLight; }

  return (
    <span style={{
      padding: '6px 14px',
      backgroundColor: bg,
      color: color,
      borderRadius: '9999px',
      fontSize: '0.82rem',
      fontWeight: 700,
      border: `1px solid ${color}40`
    }}>
      {percentage}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span style={{
    padding: '7px 18px',
    backgroundColor: present ? COLORS.greenLight : COLORS.redLight,
    color: present ? '#0A7A5E' : '#C53030',
    borderRadius: '9999px',
    fontSize: '0.84rem',
    fontWeight: 700
  }}>
    {present ? 'PRÉSENT' : 'ABSENT'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{ ...styles.summaryValue, color }}>{value}</p>
  </div>
);

// ==================== STYLES ====================
const styles = {
